[38558] = {
["id"] = 38558,
["name"] = "See Ya Later, Oscillator",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "alliance",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = true,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7541,
["mapID"] = 634,
["storyline"] = { 38036, 38052, 38053, 38057, 38058, 38059, 38060, 38210, 38558 },
["series"] = { 38053, 38057, 38058, 38059, 38060 },
["description"] = "Those jawless mooks are actually trying to salvage parts from our ship! They can't possibly appreciate superior gnomish technology... Perhaps its shiny nature is appealing to their simple inclinations. In any case, I need a crystal oscillator for our new transponder. It's the shiniest part of the whole system, they're bound to have it set aside somewhere!",
["objectivesText"] = "Collect the Crystal Oscillator . Progress: Did you find the oscillator?",
["rewardGold"] = 280900,
["rewardXP"] = 1415,
["rewardItems"] = { 123887, 237812 },
