["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922, 44940 },
["description"] = "So some old magic vrykul is helping us out? I guess that's good, but this trial of yours might be tricky. You see, the only way up that mountain, is through those big walls. You know, the ones with the mean-looking drakes on them. I scouted a bit, but couldn't get too far without those drakes trying to make lunch out of poor Duchess. The vrykul have them trained, which can't be good. I say we sneak in. I managed to snag a few grapple launchers earlier. Grab one and meet me outside the city walls.",
["objectivesText"] = "Pick up a Stormforged Grapple Launcher and meet Dread-Rider Cullen outside the wall of Hrydshal.",
["rewardGold"] = 202200,
["rewardXP"] = 1415,
["rewardItems"] = { 138111, 237812 },
