["timerSeconds"] = nil,
["sharable"] = true,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7541,
["mapID"] = 634,
["storyline"] = { 40120 },
["series"] = {  },
["description"] = "You may not know, but you stand upon the grounds of Morheim, home to the greatest warriors of the land. Our deeds were great, our valor legendary. It pains me that we see such an end. The creatures set upon us at nightfall. Our men fought bravely, but were vastly outnumbered. Now their corpses lie rotting in the sun, with no burial and no rites. This is not an end befitting to the glorious warriors of Morheim. Make it right, and you will have our thanks.",
["objectivesText"] = "Use the Smoldering Torch to burn 8 Decaying Corpses in Morheim. Progress: Have you done this task?",
["rewardGold"] = 309800,
["rewardXP"] = 1415,
["rewardItems"] = { 129725, 237812 },
["starts"] = { { ["npcID"] = 98587, ["mapID"] = 634, ["x"] = 0.782, ["y"] = 0.585 } },
["ends"] = { { ["npcID"] = 98587, ["mapID"] = 634, ["x"] = 0.782, ["y"] = 0.585 } },
