["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } },
},

[40122] = {
["id"] = 40122,
["name"] = "Cenarius, Keeper of the Grove",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = false,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7558,
["mapID"] = 641,
["storyline"] = { 38384, 40122 },
["series"] = { 39731, 39861 },
["description"] = "Ahh, Val'sharah . It has been an age since I have set foot in these sacred woods. Too long... Our work here is simple, <class>. We must call upon my mentor, Cenarius, and learn where he safeguards the Tears of Elune. With them, you will be one step closer to sealing Sargeras' Tomb and thwarting the Legion. You have many treacherous tasks in front of you. Consider your visit here a brief respite. Come, this will not take long.",
["objectivesText"] = "Speak to Malfurion Stormrage at Lorlathil in Val'sharah . Progress: Cenarius!",
