["storyline"] = { 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 41217 },
["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41218 },
["description"] = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. <class>s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts. Muffinus Chromebrew will help oversee your training and adjustment to life on the surface. He's waiting for you on the stands across the road.",
["objectivesText"] = "Meet with Muffinus Chromebrew in New Tinkertown .",
["rewardGold"] = 1000,
["rewardXP"] = 100,
["rewardItems"] = { 59039, 59040, 59041, 59042, 59043, 134123 },
