["storyline"] = { 41197, 41452, 41453, 41462, 41469, 41473, 41474, 41475, 41478, 41479, 41480, 41485, 41494 },
["series"] = {  },
["description"] = "Like most herbivores, our antlered friends will eat anything green enough to chew. However I have noticed that they seek these patches of dark grass, given their preference. I believe we can begin to earn their favor if we aid the forest in producing more of this most nutritious of stag food. I will provide you with the seeds- all you must do is locate suitable growing soil and plant them. Our magic will do the rest.",
["objectivesText"] = "Plant 5 Lush Grass Seeds in piles of Rich Soil . Progress: How goes the planting?",
["rewardGold"] = 309800,
["rewardXP"] = 6140,
["rewardItems"] = { 124640, 135558, 139791, 140240, 140251, 141941, 237812 },
