["zoneID"] = 7834,
["mapID"] = 18,
["storyline"] = { 41625, 41626, 41627, 41628, 41629, 41630, 41632 },
["series"] = {  },
["description"] = "Light's Wrath... a bold choice. Though if you believe you can control its energies, it could prove vital to our cause. Retrieving it won't be easy. It was last held by the Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it. The dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.",
["objectivesText"] = "Meet Kalec at the Violet Citadel in Dalaran.",
["rewardGold"] = 28090,
["rewardXP"] = 175,
["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 140517, 140930, 237812 },
