[41631] = {
["id"] = 41631,
["name"] = "The Nexus Vault",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = { 3, 5 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
