[42476] = {
["id"] = 42476,
["name"] = "The Deadwind Site",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = { 8 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = false,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7879,
["mapID"] = nil,
["storyline"] = { 42452, 42455, 42476, 42477, 42479 },
["series"] = { 42477, 42479 },
["description"] = "Your research spoke of an experimental site out near Karazhan. I hope there are still materials on this ritual that will aid us there. You will need to find the site and bring back anything that will help us recreate the ritual. I will dig deeper here as well.",
["objectivesText"] = "Find and retrieve information on the ritual from Arrexis's campsite near Karazhan. Progress: I trust you were successful?",
["rewardGold"] = 309800,
["rewardXP"] = 1415,
["rewardItems"] = { 127857, 128820, 128862, 141327, 141328, 141329, 173698, 237812 },
