["ends"] = {  },
["coords"] = nil,
["mapCandidates"] = { ["npc"] = {  }, ["zone"] = { 7879 } },
},

[42477] = {
["id"] = 42477,
["name"] = "Daio the Decrepit",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = { 8 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = false,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7879,
["mapID"] = nil,
["storyline"] = { 42452, 42455, 42476, 42477, 42479 },
["series"] = { 42476, 42479 },
["description"] = "That text lists someone named Daio as being instrumental to the demonic ritual. They can't possibly mean Daio the Decrepit! I never knew he was Kirin Tor. I only know him as an elderly warlock who trains young recruits in the infernal arts. This would certainly explain his change of occupation. He most likely holds key information for this to work. Though retired, I believe he is still out in the Tainted Scar in the Blasted Lands. You should seek him out.",
["objectivesText"] = "Fly to the Tainted Scar in the Blasted Lands and get information from Daio the Decrepit. Progress: Well, what did Daio have to say?",
["rewardGold"] = 309800,
["rewardXP"] = 1415,
["rewardItems"] = { 127857, 128820, 128862, 140192, 141330, 173699, 237812 },
["starts"] = {  },
["ends"] = {  },
["coords"] = nil,
["mapCandidates"] = { ["npc"] = {  }, ["zone"] = { 7879 } },
},

[42479] = {
["id"] = 42479,
["name"] = "The Mage Hunter",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = { 8 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = false,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7879,
["mapID"] = nil,
["storyline"] = { 42452, 42455, 42476, 42477, 42479 },
["series"] = { 42476, 42477 },
["description"] = "And with that, we have what we need to recreate the ritual... however flawed it may be. It must be conducted somewhere highly visible so that word reaches our target swiftly. I've heard reports that the Legion is heavily invested in the Faronaar region of Azsuna. An excellent place to begin a ritual they won't want us to complete. The chances of us dying horribly are exceptionally high.",
["objectivesText"] = "Recreate Arrexis' ritual in Faronaar and defeat Balaadur. Progress: Do you have it?",
["rewardGold"] = 606600,
["rewardXP"] = 2125,
["rewardItems"] = { 127857, 128820, 128862, 237812 },
["starts"] = {  },
["ends"] = {  },
["coords"] = nil,
["mapCandidates"] = { ["npc"] = {  }, ["zone"] = { 7879 } },
},

[42483] = {
["id"] = 42483,
["name"] = "Put It All on Red",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "group" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = true,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7541,
["mapID"] = 634,
["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 },
["series"] = {  },
["description"] = "All right, I've got one last beasty to send you after. He's a bit far out, but trust me, it'll be worth it. This one I put a huge wager on! Along the eastern coast swims a great shark the locals call Steelscale. They say his hide is near impenetrable. But you're gonna prove them wrong, aren't ya chum? Bring me his fin, and those tauren will have to fork over a princely sum.",
["objectivesText"] = "Collect Steelscale's Fin from Steelscale in Citrine Bay. Progress: Hmm...",
["rewardGold"] = 0,
["rewardXP"] = 1415,
["rewardItems"] = { 132203, 138024, 138111, 138123, 138125, 138127, 138129, 138131, 138133, 138135 },
