[42635] = {
["id"] = 42635,
["name"] = "The Mystery of Dreyrgrot",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = true,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7541,
["mapID"] = 634,
["storyline"] = { 42635, 42639, 42640, 42641, 42645 },
["series"] = { 42639, 42641 },
["description"] = "Well met, good chap! I was on my way to study the local murlocs when I stumbled upon these most peculiar ruins. Those pirates over yonder arrived first, and it appears they've unleashed some ancient evil. I would be remiss to let such an evil run rampant, but we should learn more of it before we proceed, lest we end up like those chaps. I spied the crew bringing back some tablets from the ruins. If you can bring them to me, I may be able to decipher the nature of this evil.",
["objectivesText"] = "Gather 4 Ancient Dreyrgrot tablets from the pirate ships outside of Dreyrgrot. Progress: How goes the hunt for knowledge?",
["rewardGold"] = 202200,
