[42933] = {
["id"] = 42933,
["name"] = "The Troggs that Fel to Earth",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "none",
["requiredClasses"] = { 7 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = false,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 5042,
["mapID"] = 207,
["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 },
["series"] = { 42931, 42932, 42935, 42937 },
["description"] = "\"Demons\" you say? A \"Burning Legion?\" Hrmph! Nothing burns here but for my ire, shaman, and if these monsters think to corrupt my domain, they will be crushed beneath my dainty beautiful feet! I have not seen this hammer of yours, but the stone troggs witnessed everything that fell from the sky. Moreover, they've been running amok in the Pale Roost ever since the green fire landed near their home. Be a dear and lay waste to the Felrock Troggs west of here. Perhaps you can get one of them to talk.",
["objectivesText"] = "Slay 25 Felrock Troggs in the Pale Roost. Progress: Well? Have you given them a solid thrashing?",
["rewardGold"] = 309800,
["rewardXP"] = 1415,
["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 },
["starts"] = { { ["npcID"] = 42465, ["mapID"] = 207, ["x"] = 0.563, ["y"] = 0.125 } },
["ends"] = { { ["npcID"] = 42465, ["mapID"] = 207, ["x"] = 0.563, ["y"] = 0.125 } },
["coords"] = { ["x"] = 0.563, ["y"] = 0.125, ["mapID"] = 207, ["source"] = "quest_giver" },
["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } },
},

[42935] = {
["id"] = 42935,
["name"] = "Stone Drake Rescue",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "none",
["requiredClasses"] = { 7 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = false,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 5042,
["mapID"] = 207,
["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 },
["series"] = { 42931, 42932, 42933, 42937 },
["description"] = "When that demon of yours fell into my realm he must have done something to the troggs. They were never a threat to my beloved stone drakes before. Now they're loose all over the Pale Roost, subduing drakes on the ground. Put a stop to this insult at once, and free those drakes! They may be of use to us later.",
["objectivesText"] = "Rescue 6 Stone Drakes in the Pale Roost by defeating the troggs that torment them. Progress: What of my precious little drakes, hm?",
["rewardGold"] = 309800,
["rewardXP"] = 1415,
["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 },
