["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } },
},

[42936] = {
["id"] = 42936,
["name"] = "Clutch Play",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "none",
["requiredClasses"] = { 7 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = false,
