["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 5042,
["mapID"] = 207,
["storyline"] = { 40224, 42931, 42932, 42933, 42935, 42936, 42937 },
["series"] = {  },
["description"] = "I confess the stone drake broodmother and I have had a rocky relationship in the past. She supported Deathwing during the Cataclysm, you know. But Aeosera has been put back in her place and it is my responsibility to protect her. The problem is that she refuses to abandon her eggs, even in the midst of a trogg attack. You're a shaman! Use your natural magnetism to reassemble fallen Opalescent Guardians in the Pale Roost. Escort them to Aeosera so they can carry her eggs to safety of my bosom.",
["objectivesText"] = "Escort 5 Opalescent Guardians to Aeosera. Progress: Step to it, <class>! Reassemble those guardians and take them to Aeosera!",
["rewardGold"] = 202200,
["rewardXP"] = 1415,
["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 },
