[43309] = {
["id"] = 43309,
["name"] = "The Perfect Opportunity",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = true,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7637,
["mapID"] = 680,
["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 },
["series"] = {  },
["description"] = "I have heard whispers from Suramar City. Recent unrest in the city has prompted the nobles to seek another advisor to fill Elisande's council. Such positions are rarely offered and hotly contested. This is the perfect opportunity and Ly'leth is the perfect candidate. Fate smiles upon our cause! I know she has historically chosen to avoid such politics and maneuvering, but we must now ask her to join the fray. Seek her out at the Waning Crescent and ensure her victory.",
["objectivesText"] = "Meet Ly'leth Lunastre at the Waning Crescent. Progress: Thalyssra asks much of me.",
["rewardGold"] = 20220,
["rewardXP"] = 770,
["rewardItems"] = { 140255, 140409, 140421, 140422, 141680, 141955, 237812 },
["starts"] = { { ["npcID"] = 97140, ["mapID"] = 680, ["x"] = 0.367333, ["y"] = 0.465333 } },
["ends"] = { { ["npcID"] = 107632, ["mapID"] = 680, ["x"] = 0.46, ["y"] = 0.69 } },
["coords"] = { ["x"] = 0.367333, ["y"] = 0.465333, ["mapID"] = 680, ["source"] = "quest_giver" },
["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } },
},

[43310] = {
["id"] = 43310,
["name"] = "Either With Us",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
