["expansion"] = 6,
["zoneID"] = 7637,
["mapID"] = 680,
["storyline"] = { 43309, 43310, 43311, 43312, 43313, 43315, 43317, 43318, 44040, 44053 },
["series"] = {  },
["description"] = "Thalyssra asks much of me, but our cause is worth the risks. The title of advisor would grant us enormous influence. Information. Access. I could change this rebellion. I could save so many lives. I will need strong endorsement to ascend, though. There are many houses who stand with me by virtue of my family's name. Some are more hesitant. Lady Aurore of House Astravar is the most prominent of these. Seek her out. Offer your aid in my stead. Earn her trust and the rest will follow.",
["objectivesText"] = "Speak to Lady Aurore .",
["rewardGold"] = 28090,
["rewardXP"] = 770,
