[43334] = {
["id"] = 43334,
["name"] = "The Coming Storm",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = { 7 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
