["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 8046,
["mapID"] = 379,
["storyline"] = { 39771, 43334, 43338 },
["series"] = {  },
["description"] = "You saved us all, my friend! Truly you embody all the elements stand for. If the Earthen Ring is to prevail, we will need weapons of great power. I know where to find some. After the Pandaren Campaign, the weapons of the storm god Ra-den were discovered beneath the Throne of Thunder. None have been able to wield them, so great is their power. They were placed in the care of the White Tiger, who will give them only to one who is worthy. Come <name>! Travel with me to Pandaria and we will prove your worth!",
["objectivesText"] = "Travel to Pandaria and speak to the White Tiger at his temple.",
["rewardGold"] = 154900,
["rewardXP"] = 710,
["rewardItems"] = { 124124, 128819, 128911, 128935, 137209, 137374, 139506, 139698, 139701, 139705, 139879, 140517, 140932, 237812 },
