["expansion"] = 6,
["zoneID"] = 7503,
["mapID"] = 650,
["storyline"] = { 42384, 42385, 42386, 42387, 42388, 42389, 42390, 42391, 42392, 42393, 42395, 42410, 42411, 43335 },
["series"] = { 42390, 42392 },
["description"] = "The life of a hunter should never be dull. Living in the wild you never know what will happen next, but you survive on skill and instinct. Show me you have the basic survival skills to live off the land.",
["objectivesText"] = "Show your survival skill by building a campfire from chopped wood , and cooking a steak over an open flame. Progress: You need to eat to survive in the wild. Boar meat makes an excellent meal when cooked over an open flame. It should not be eaten raw, however. There are many berries that grow in this region. Some are edible, while others cause minor sickness when ingested. You can often tell which are safe to eat by their smell. A sweet aroma often indicates the berry is unsafe to eat. The best firewood can be obtained from dying trees. They are easily identified by their fading, purple leaves.",
["rewardGold"] = 202200,
["rewardXP"] = 1415,
["rewardItems"] = { 124119, 137609, 137612, 237812 },
["starts"] = { { ["npcID"] = 107425, ["mapID"] = 650, ["x"] = 0.366, ["y"] = 0.354 } },
["ends"] = { { ["npcID"] = 107425, ["mapID"] = 650, ["x"] = 0.366, ["y"] = 0.354 } },
