[43391] = {
["id"] = 43391,
["name"] = "Secrets of the Void",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = { 5 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
