["series"] = {  },
["description"] = "Our leader was murdered for her beliefs, or so most would believe. Natalie Seline knew her fate, and took steps to protect herself from an inevitable death. The night her attackers came, Natalie sent her spirit to the Void, its location known only to Natalie herself. She penned a spell to retrieve it in one of her many journals, but the tome has since fallen into the hands of those who wished her dead in the first place. Without her journal, we will never be able to recover her spirit.",
["objectivesText"] = "Recover Natalie's Journal from Twilight Lord Urgrok. Progress: We watch over Natalie's body, forever hopeful that her spirit will return.",
["rewardGold"] = 202200,
["rewardXP"] = 6140,
["rewardItems"] = { 128825, 128827, 128868, 139506, 139757, 139759, 139772, 140517, 140930, 237812 },
