[43468] = {
["id"] = 43468,
["name"] = "Blood for the Wolfe",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = { 4 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = { "loremaster" },
["timerSeconds"] = nil,
["sharable"] = false,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7502,
["mapID"] = nil,
["storyline"] = { 42684, 42730, 43468, 43829, 43841, 43852, 43958, 44041, 44116, 44117, 44155, 44177, 44178, 44180, 44181, 44183, 91620 },
["series"] = { 42684, 43249, 43250, 43253 },
["description"] = "We have a request in from Winstone Wolfe. He says that he needs a rather large amount of demon blood. He was not specific what for, and I did not ask. I am inclined to do this for him with all expediency. The Wolf rarely asks for anything, so when he does, we jump. He gets results, one-hundred percent of the time and then some. We should show him the same professional courtesy.",
["objectivesText"] = "Collect 50 Fel Blood . Progress: The clock is ticking, <name>. Do you have the blood?",
["rewardGold"] = 561800,
["rewardXP"] = 1770,
["rewardItems"] = { 127837, 128476, 128870, 128872, 136786, 137677, 139506, 139739, 139742, 139746, 140517, 140931, 237812 },
["starts"] = {  },
["ends"] = {  },
["coords"] = nil,
["mapCandidates"] = { ["npc"] = {  }, ["zone"] = { 7502 } },
},

[43469] = {
["id"] = 43469,
["name"] = "Where In the World is Mathias?",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = { 4 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = { "loremaster" },
["timerSeconds"] = nil,
["sharable"] = false,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7502,
["mapID"] = nil,
["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 },
["series"] = { 43470, 43479, 43485 },
["description"] = "Master Mathias Shaw is the leader of the Alliance intelligence organization known as SI:7. And apparently, he is now a dreadlord. Or rather, a very clever dreadlord has taken his place while he is being held captive somewhere. It is imperative that we reveal this imposter to the new king of Stormwind. If we fail to do so, then the Alliance will surely be eaten alive from within and the Burning Legion will win this war for a certainty.",
["objectivesText"] = "Use the Scouting Map and complete the \"Where In the World is Mathias Shaw?\" missions.",
["rewardGold"] = 202200,
["rewardXP"] = 6140,
["rewardItems"] = { 237812 },
["starts"] = {  },
["ends"] = {  },
["coords"] = nil,
["mapCandidates"] = { ["npc"] = {  }, ["zone"] = { 7502 } },
},

[43470] = {
["id"] = 43470,
["name"] = "Pruning the Garden",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = { 4 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = false,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7502,
["mapID"] = nil,
["storyline"] = { 37448, 37494, 37666, 37689, 43469, 43470, 43479, 43485, 43508, 43723, 43724 },
["series"] = { 43469, 43479, 43485 },
["description"] = "In a very real sense, the Uncrowned are gardeners. We snip and trim here and there. One clipping of a single branch may seem nonsensical until you step back and look at the garden as a whole. On the greater theater of the Broken Isles, we must act decisively. The forces that arrayed against Azeroth are moving quickly. We need to prune some very ugly flowers to make our garden beautiful again, wouldn't you agree, <name>?",
["objectivesText"] = "Complete 10 World Quests.",
["rewardGold"] = 808800,
