["series"] = { 43487, 49812 },
["description"] = "I have been studying the Codex of Command that you recovered from Faronaar. It is important to Balnazzar, but WHY? What does it say? I'm sure we could gain valuable knowledge if we could just crack this code. I have a friend who might be able to help us: a priestess named Delas Moonfang . She has been studying Eredun, the language of the demons. Take the sigil to her in Dalaran. Tell her I sent you.",
["objectivesText"] = "Speak to Delas Moonfang in Dalaran.",
["rewardGold"] = 28090,
["rewardXP"] = 175,
