},

[43487] = {
["id"] = 43487,
["name"] = "Assault on Violet Hold: The Fel Lexicon",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = { 2 },
["requiredRaces"] = {  },
