["series"] = { 43486, 49812 },
["description"] = "I have been studying the language of the demons, but it has been difficult to get my hands on written material. I have heard rumor of a book called the Fel Lexicon , written by an ancient scholar who spoke both eredun and draenei. If I could just get my hands on that book, I could learn so much! I heard that this book might be in the hands of a powerful prisoner inside the Violet Hold. Bring me this book, and my work here will go much faster.",
["objectivesText"] = "Collect a Fel Lexicon from a powerful prisoner inside Violet Hold. Progress: I am fairly adept in twelve different languages, and I hope to add more to the list.",
["rewardGold"] = 202200,
["rewardXP"] = 1415,
["rewardItems"] = { 120978, 128823, 128866, 139445, 139506, 139690, 139693, 139697, 140517, 140929, 237812 },
