["storyline"] = { 43494 },
["series"] = {  },
["description"] = "Good news, Highlord! We have recruited a paladin trainer named Commander Born . He is a hard teacher, but has trained some of the greatest paladin knights in recent times. We are lucky to have his services. Go speak to him, and train a squad of Silver Hand Knights.",
