["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 8046,
["mapID"] = 205,
["storyline"] = { 40341, 43644, 43645 },
["series"] = {  },
["description"] = "I assure you the legends are true: Sharas'dal, the Scepter of Tides, was forged around living waters of the Well of Eternity. It gave Azshara dominion over life itself. I have sent shaman throughout the world looking for it, but the only one to ever find it has gone missing. Wavespeaker Adelee said she had tracked the scepter to the Ruins of Vashj'ir, but we haven't heard from her since. <name>! Come with me to the ocean depths. Let's track down our missing shaman and get that artifact!",
["objectivesText"] = "Travel to the Ruins of Vashj'ir with Erunak. Progress: I can transport us to the depths. Step into the bubble here... It's mostly safe.",
["rewardGold"] = 30900,
["rewardXP"] = 175,
["rewardItems"] = { 54465, 63542, 63543, 63544, 63545, 63546, 63547, 63548, 63549, 128819, 128911, 128935, 131432, 131433, 169354, 218343, 225245, 226146, 227792, 237812 },
