["ends"] = { { ["npcID"] = 96530, ["mapID"] = 205, ["x"] = 0.435, ["y"] = 0.632 } },
["coords"] = { ["x"] = 0.435, ["y"] = 0.632, ["mapID"] = 205, ["source"] = "quest_giver" },
["mapCandidates"] = { ["npc"] = { 205 }, ["zone"] = { 8046 } },
},

[43645] = {
["id"] = 43645,
["name"] = "Wavespeaker's Trail",
["level"] = 10,
["requiredLevel"] = 10,
["faction"] = "both",
["requiredClasses"] = { 7 },
