["description"] = "Magic has long been a vice of the elves. It shaped us, and lifted us out of the darkness - but without balance, it also threatens to unmake us. The shal'dorei are too proud to admit it, but they are the product of indulgence. They live without harmony. But I sense potential among the Nightfallen . Losing everything has humbled them. It has made them stronger. Stay the course, $p. Help the Nightfallen rise up.",
["objectivesText"] = "Reach Revered with The Nightfallen . Progress: Have you felt it? Change is on the wind.",
["rewardGold"] = 101100,
["rewardXP"] = 3070,
["rewardItems"] = { 141681, 141685, 237812 },
["starts"] = { { ["npcID"] = 107126, ["mapID"] = 680, ["x"] = 0.2972, ["y"] = 0.4404 } },
["ends"] = { { ["npcID"] = 107126, ["mapID"] = 680, ["x"] = 0.2972, ["y"] = 0.4404 } },
["coords"] = { ["x"] = 0.2972, ["y"] = 0.4404, ["mapID"] = 680, ["source"] = "quest_giver" },
["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } },
},

