["mapID"] = 680,
["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 },
["series"] = {  },
["description"] = "Greetings, Outlander. I am Victoire . I served Elisande while she maintained peace in the city. I fought beside demons and worse for the greater good. The massacre at the Waning Crescent made it clear that she no longer serves the Nightborne. She serves only herself. There are others who feel as I do. They simply need proof that there is another way. The Dusk Lily is not unknown to us- try showing it to those now guarding Astravar Harbor. They have seen the worst of Elisande's cruelty.",
["objectivesText"] = "Use the Dusk Lily Sigil on Duskwatch Subjugators to identify 5 Deserters. Progress: Did you find more like me?",
["rewardGold"] = 309800,
["rewardXP"] = 6140,
["rewardItems"] = { 142065, 143488, 237812 },
