["zoneID"] = 7637,
["mapID"] = 680,
["storyline"] = { 44722, 44723, 44724, 44725, 44726, 44727, 44814, 45261 },
["series"] = {  },
["description"] = "Our new friend brings us some disturbing information. She claims to have seen a large number of citizens dragged from Starcaller Retreat in chains. Their destination appears to be Astravar Harbor. Those taken to the harbor have yet to return, however. Worse yet, the area is now overrun with demons. I need you to find out where these people went. Infiltrate the harbor and gather any information you can. Start with the Legion filth- their corpses may point us in the right direction.",
["objectivesText"] = "Acquire a Legion Communicator from demons in Astravar Harbor. Progress: Have you learned where the captives have been taken?",
["rewardGold"] = 309800,
["rewardXP"] = 6140,
["rewardItems"] = { 142066, 237812 },
