["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } },
},

[45261] = {
["id"] = 45261,
["name"] = "Continuing the Cure",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
