[45294] = {
["id"] = 45294,
["name"] = "Return to Karazhan: High Stress Hiatus",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
