},

[45295] = {
["id"] = 45295,
["name"] = "Return to Karazhan: Clearing Out the Cobwebs",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "dungeon" },
["flags"] = {  },
["timerSeconds"] = nil,
