[45915] = {
["id"] = 45915,
["name"] = "The Folly of Levia Laurance",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "none",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
