["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = nil,
["mapID"] = nil,
["storyline"] = { 45915 },
["series"] = {  },
["description"] = "Levia Laurance was once a member of the Kirin Tor, long ago, and a good friend. Dabbling in shadow magic got her banned from the city, but she knows the streets too well to keep her out for good. Levia has disappeared, and I'm gravely concerned. Her work may have attracted the attention of the Legion. It has before. It would be very dangerous for all of us if her knowledge fell into their hands. She was last seen at the Militant Mystic. Ask around there and see if you can pick up her trail.",
["objectivesText"] = "Ask around the city for information on Levia Laurance.",
["rewardGold"] = 309800,
["rewardXP"] = 6140,
["rewardItems"] = {  },
["starts"] = {  },
["ends"] = {  },
["coords"] = nil,
["mapCandidates"] = { ["npc"] = {  }, ["zone"] = {  } },
},

[45916] = {
