[46078] = {
["id"] = 46078,
["name"] = "Holy: The Bradensbrook Investigation",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "alliance",
["requiredClasses"] = { 5 },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
