["zoneID"] = 7502,
["mapID"] = 641,
["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200 },
["series"] = { 46079, 46080, 46082, 47003, 47004, 47005, 47006, 47027, 47029 },
["description"] = "We have uncovered forged orders from the Shore. They have a fel influence about them. They guide the reader to believe they are legitimate. It orders Black Rook Hold to attack a \"demonic enclave\" just south of their walls. There's only one enclave they could be talking about, Bradensbrook! Is it possible these would be able to convince the undead to attack Bradensbrook? You should head there immediately and either warn them, or render aid. Specialization: Holy Priest",
["objectivesText"] = "Go to Bradensbrook in Val'sharah.",
["rewardGold"] = 28090,
["rewardXP"] = 770,
["rewardItems"] = { 237812 },
["starts"] = {  },
["ends"] = { { ["npcID"] = 118752, ["mapID"] = 641, ["x"] = 0.422, ["y"] = 0.59 } },
