["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } },
},

[46079] = {
["id"] = 46079,
["name"] = "Aid on the Front Lines",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
