["zoneID"] = 7558,
["mapID"] = 641,
["storyline"] = { 45864, 46078, 46079, 46080, 46082, 46106, 46107, 46200, 47003, 47004, 47005, 47006 },
["series"] = { 46078, 46080, 46082, 47003, 47004, 47005, 47006, 47027, 47029 },
["description"] = "When we settled here, that Hold was just a quiet creepy place that we avoided. Then the elves came back from the dead. With your help we thought it was mostly handled. But now it feels like an army is attacking us! We could use more healing at our defense lines. More undead arrive and we have less and less protectors each wave. Any aid to our wounded would be welcomed!",
["objectivesText"] = "Give aid to the wounded on the east, west, and south defense lines of Bradensbrook. Progress: We can't take anymore losses.",
["rewardGold"] = 30900,
["rewardXP"] = 770,
["rewardItems"] = { 237812 },
["starts"] = { { ["npcID"] = 118752, ["mapID"] = 641, ["x"] = 0.422, ["y"] = 0.59 } },
