["mapID"] = 84,
["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 },
["series"] = { 46272, 46275, 46282 },
["description"] = "Anduin hasn't been the same since you brought him his father's compass. He has become listless... distracted. We attempted to console him, to no avail. Yesterday morning, he left the keep without so much as a word. I ordered the guards to follow him, of course. He went to pray at the cathedral, where he's remained ever since. You brought this melancholy upon him! You must convince the boy to resume his duties. There's a war to be won!",
["objectivesText"] = "Look for King Anduin Wrynn inside Stormwind Cathedral.",
["rewardGold"] = 210675,
["rewardXP"] = 4605,
