[46684] = {
["id"] = 46684,
["name"] = "The Legend of the Elderhide",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = { "leatherworking" },
["categories"] = { "normal" },
