["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 7543,
["mapID"] = 646,
["storyline"] = { 46684 },
["series"] = {  },
["description"] = "Leatherworking is one of the oldest forms of craftsmanship in the world. Hides of animals were the first clothing. Legends tell of a particular form of leather curing that has been lost to us in modern times. Combining magic of the earth with some of the finest leathers ever found, this technique has been recreated by yours truly through careful analysis and my understanding of style. To begin, you must capture some ancient wisps to channel the exact nature magic for the curing process.",
["objectivesText"] = "Capture Ancient Wisps in Val'sharah. Progress: Have you found an Ancient Wisp ?",
["rewardGold"] = 309800,
["rewardXP"] = 6140,
["rewardItems"] = { 124113, 124124, 146659, 146669, 146712 },
