},

[46687] = {
["id"] = 46687,
["name"] = "The Wisp and the Nightmare",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = { "leatherworking" },
