["zoneID"] = 7543,
["mapID"] = 646,
["storyline"] = { 46698 },
["series"] = { 46697, 46699, 46700, 46701 },
["description"] = "The Dragonhunter lived in a time before history was written and her tale was passed down orally to us. It seems that dragons tormented her people and after her village temple was destroyed, she rallied the local tribes, became a queen and killed all of the dragons. She was then banished for some reason and wandered until her death, alone. What proves the story is a piece of draconic slag from left over from a metal idol in her birth village. Dargul the Underking has it now. Forge a hammer from it.",
["objectivesText"] = "Defeat Dargul in Neltharion's Lair in Mythic difficulty and create a hammer from his Red-Hot Draconic Slag Progress: Did you find the draconic slag from the Dragonhunter's birth village temple? When you do, forge a hammer from it.",
["rewardGold"] = 202200,
["rewardXP"] = 6140,
["rewardItems"] = { 146704, 146705 },
["starts"] = { { ["npcID"] = 120221, ["mapID"] = 646, ["x"] = 0.412, ["y"] = 0.594 } },
["ends"] = { { ["npcID"] = 120221, ["mapID"] = 646, ["x"] = 0.412, ["y"] = 0.594 } },
["coords"] = { ["x"] = 0.412, ["y"] = 0.594, ["mapID"] = 646, ["source"] = "quest_giver" },
["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } },
},

