["mapID"] = 634,
["storyline"] = { 45486, 45522, 45523, 45524, 45525, 45862, 46340, 47049 },
["series"] = {  },
["description"] = "A scout from Stormheim arrived yesterday with a significant discovery - these ancient scrolls. Within they contain a Valkyra prophecy of a new vrykul ruler - one who could turn the Tideskorn against the Legion. It complicates matters that this vrykul may in fact be Skovald's heir. Take the scrolls, find the heir, and bring her to the Valkyra. I think the outcasts they refer to are the vrykul of Jandvik, so that would be a good place to start. Specialization: Demonology Warlock",
["objectivesText"] = "Search Jandvik for the vrykul mentioned in the scrolls.",
["rewardGold"] = 20220,
["rewardXP"] = 770,
["rewardItems"] = { 144457 },
