[47134] = {
["id"] = 47134,
["name"] = "Foiling the Legion's Jailbreak",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = true,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 8899,
["mapID"] = nil,
["storyline"] = { 47104, 47134, 47182, 47287, 47554 },
["series"] = { 47102, 47104, 47182, 47554 },
["description"] = "High Inquisitor Raalgar has some connection to the fel here on Argus that makes him unkillable. Long ago, the naaru imprisoned him on the Arcatraz. When the forces of Kael'thas Sunstrider attacked the citadel, we were forced to flee on the Exodar. Some Legion prisoners escaped the Arcatraz when last the Legion invaded Azeroth, but Raalgar did not. Stop them from freeing him and I will study the source of his immortality so it can be broken. I can get you close. The rest is up to you.",
["objectivesText"] = "Find High Inquisitor Raalgar before the Legion frees him. Progress: We must stop High Inquisitor Raalgar!",
["rewardGold"] = 151650,
