["mapID"] = 882,
["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 },
["series"] = {  },
["description"] = "I have an idea. This construct will be of use to us. We simply need to jolt it awake. We once stored great quantities of energy in conduits throughout the Conservatory. They are still functional, but only just. Take this. <Y'mera hands you a brightly glowing crystal.> It will provide a small burst of magic that should help stabilize an erratic conduit. I think I have enough stored for eight or so. Stabilizing a few should allow us to access the whole network.",
["objectivesText"] = "Stabilize 8 Erratic Power Conduits .",
["rewardGold"] = 210675,
["rewardXP"] = 6140,
