[48199] = {
["id"] = 48199,
["name"] = "The Burning Heart",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
