["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 8574,
["mapID"] = nil,
["storyline"] = { 47473, 48199, 48200, 48201, 48202, 48929 },
["series"] = {  },
["description"] = "The loss of Xe'ra is a blow, especially to Turalyon. But even the Light Mother could not be allowed to force destiny upon us. I wish Illidan had found another way to refuse her... but I too have had choices imposed upon me by the naaru. This must not distract us from our mission. Now that we have the Army of the Light survivors with us, it is time to press our attack. We need a foothold on the Antoran Wastes from which we can assault the Burning Throne. It is time to deprive Sargeras of his prize!",
["objectivesText"] = "Use the Navigation Console to travel to the Antoran Wastes .",
["rewardGold"] = 77400,
["rewardXP"] = 6140,
["rewardItems"] = { 237812 },
["starts"] = {  },
["ends"] = {  },
["coords"] = nil,
["mapCandidates"] = { ["npc"] = {  }, ["zone"] = { 8574 } },
},

[48200] = {
["id"] = 48200,
["name"] = "Securing a Foothold",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "normal" },
["flags"] = {  },
["timerSeconds"] = nil,
["sharable"] = true,
["event"] = nil,
["unknownQuickfacts"] = {  },
["expansion"] = 6,
["zoneID"] = 8899,
["mapID"] = nil,
["storyline"] = { 47473, 48199, 48200, 48201, 48202, 48929 },
["series"] = {  },
["description"] = "Alleria and I have scouted this area before, alongside some of our best soldiers. We stationed encampments on either side of our current position, but I fear they will have come under heavy attack. They need reinforcements. Our first order of business is to set up a teleportation beacon directly below the Vindicaar. From there, we will have access to both fronts. Speak to Romuul when you are ready to head down to the surface.",
["objectivesText"] = "Travel to the Antoran Wastes and place the Lightforged Beacon. Progress: We need that teleportation beacon set up if we are to reinforce our positions.",
["rewardGold"] = 30900,
["rewardXP"] = 6140,
["rewardItems"] = { 237812 },
["starts"] = {  },
["ends"] = {  },
["coords"] = nil,
["mapCandidates"] = { ["npc"] = {  }, ["zone"] = { 8899 } },
},

[48201] = {
["id"] = 48201,
["name"] = "Reinforce Light's Purchase",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
