["mapID"] = nil,
["storyline"] = { 47416, 47691, 47853, 47854, 47855, 47856, 47995, 48344, 48345 },
["series"] = {  },
["description"] = "We have a problem, <name>. The Legion has come to Eredath . When you claimed the Sigil it was as if we announced our presence to all of Argus. The eyes of Antorus are firmly upon us. Just wait. It gets worse. Velen took Captain Fareeya and her forces into the Arinor Gardens area to search for the Crest of Knowledge. To my knowledge, they are all now behind enemy lines. Come with me to the Conservatory. We need to bring Velen and the others back before it is too late.",
["objectivesText"] = "Meet Turalyon at the Conservatory of the Arcane.",
["rewardGold"] = 77400,
["rewardXP"] = 770,
["rewardItems"] = { 237812 },
["starts"] = {  },
["ends"] = {  },
["coords"] = nil,
["mapCandidates"] = { ["npc"] = {  }, ["zone"] = { 8899 } },
},

