[49015] = {
["id"] = 49015,
["name"] = "Antorus, the Burning Throne: The Death of a Titan",
["level"] = 45,
["requiredLevel"] = 45,
["faction"] = "both",
["requiredClasses"] = {  },
["requiredRaces"] = {  },
["requiredProfessions"] = {  },
["categories"] = { "raid" },
